function uid(){return crypto.randomUUID ? crypto.randomUUID() : String(Date.now())+Math.random();}
function money(value,currency="INR"){try{return new Intl.NumberFormat(undefined,{style:"currency",currency:currency||"INR",maximumFractionDigits:2}).format(Number(value||0));}catch{return String(value||0);}}
function today(){return new Date().toISOString().slice(0,10);}
function Field({label,children,...props}){return <label className="field"><span>{label}</span>{children||<input {...props}/>}</label>}
function Empty({title="Nothing here yet",text="Add your first record to get started."}){return <div className="empty"><strong>{title}</strong><small>{text}</small></div>}
function Modal({title,onClose,children}){return <div className="modal-backdrop" onMouseDown={onClose}><div className="modal" onMouseDown={e=>e.stopPropagation()}><div className="modal-head"><h3>{title}</h3><button className="icon-button" onClick={onClose}>×</button></div>{children}</div></div>}
function Stat({label,value,sub}){return <div className="stat-card"><span>{label}</span><strong>{value}</strong><small>{sub}</small></div>}

